package br.com.sistemacardapio.complemento;import java.util.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import jakarta.validation.Valid;
@RestController@RequestMapping("/api/grupos-complementos")@PreAuthorize("hasRole('ADMIN_EMPRESA')")public class GrupoComplementoController{private final GrupoComplementoService s;public GrupoComplementoController(GrupoComplementoService s){this.s=s;}@GetMapping public List<GrupoComplementoService.Response>listar(){return s.listar();}@PostMapping@ResponseStatus(HttpStatus.CREATED)public GrupoComplementoService.Response criar(@Valid@RequestBody GrupoComplementoService.Request r){return s.criar(r);}@PutMapping("/{id}")public GrupoComplementoService.Response atualizar(@PathVariable UUID id,@Valid@RequestBody GrupoComplementoService.Request r){return s.atualizar(id,r);}}
